import kotlin.reflect.KProperty

class Box {
    private var v = 0
    operator fun getValue(thisRef: Any?, p: KProperty<*>) = v
    operator fun setValue(thisRef: Any?, p: KProperty<*>, n: Int) { v = n }
}

val shared = Box()
var a: Int by shared
var b: Int by shared

fun main() {
    a = 1
    b = 2
    println("$a $b")
}

class ArgString : ReadWriteProperty<Fragment, String> {
    override fun getValue(thisRef: Fragment, property: KProperty<*>): String =
        thisRef.requireArguments().getString(property.name)!!

    override fun setValue(thisRef: Fragment, property: KProperty<*>, value: String) {
        val args = thisRef.arguments ?: Bundle().also { thisRef.arguments = it }
        args.putString(property.name, value)
    }
}

class ProfileFragment : Fragment() {
    var userId: String by ArgString()
}

class BoolPref(
    private val prefs: SharedPreferences,
    private val key: String,
    private val default: Boolean,
) : ReadWriteProperty<Any?, Boolean> {
    override fun getValue(thisRef: Any?, property: KProperty<*>) =
        prefs.getBoolean(key, default)

    override fun setValue(thisRef: Any?, property: KProperty<*>, value: Boolean) {
        prefs.edit().putBoolean(key, value).apply()
    }
}

class Settings(prefs: SharedPreferences) {
    var darkMode by BoolPref(prefs, "dark_mode", false)
}

interface Greeter { fun greet(): String }
class En : Greeter { override fun greet() = "Hello" }
class Fr : Greeter { override fun greet() = "Bonjour" }

class Wrapper(var inner: Greeter) : Greeter by inner

fun main() {
    val w = Wrapper(En())
    w.inner = Fr()
    println(w.greet())
    println(w.inner.greet())
}

